record.field:
if record and record.state == 'draft':
    activity_xmlid = 'fmcg_business_automation.mail_activity_type_purchase_order_confirm_draft'
    activity_type = env.ref(activity_xmlid)
    existing_activity = record.activity_ids.filtered_domain([
        ('active', '=', True),
        ('activity_type_id', '=', activity_type.id),
    ])
    if not existing_activity:
        record.activity_schedule(
            activity_xmlid,
            user_id=(record.user_id or env.user).id,
        )

if record and record.res_model == 'purchase.order':
    order = env['purchase.order'].with_user(env.uid).browse(record.res_id).exists()
    if order and order.state in ('draft', 'sent'):
        product_lines = order.order_line.filtered_domain([
            ('display_type', '=', False),
            ('is_downpayment', '=', False),
            ('product_id', '!=', False),
        ])
        if not product_lines:
            raise UserError('Thêm ít nhất một dòng sản phẩm trước khi xác nhận đơn mua hàng.')

        order.with_context(validate_analytic=True).button_confirm()
